<template><Teleport to="body"><div v-if="open" class="monitor-modal-backdrop" @click.self="$emit('close')"><section class="monitor-modal scene-registration" role="dialog" aria-modal="true" aria-label="模型坐标配准" @keydown.esc="$emit('close')"><header><div><h2>模型坐标配准</h2><small>将真实定位坐标映射到校园模型</small></div><button class="icon-button" aria-label="关闭配准窗口" @click="$emit('close')"><X :size="20"/></button></header><form class="monitor-modal-body" @submit.prevent="save"><fieldset :disabled="busy||!formReady||!auth.can('devices')"><p v-if="loading" class="dialog-note" role="status">正在读取已保存的配准配置…</p><p class="registration-description">请填写现场测得的坐标关系。模型位置 = 原点 + Y 轴旋转 × 定位坐标 × 比例。模型坐标与现场坐标的 Y 轴均为竖直方向。</p><div class="field-triple"><label v-for="axis in axes" :key="axis" class="form-field">模型原点 {{axis.toUpperCase()}}<input v-model.number="form.origin[axis]" type="number" step="any" required/></label></div><div class="field-pair"><label class="form-field">坐标旋转（°）<input v-model.number="form.yawDeg" type="number" step="any" required/></label><label class="form-field">模型单位 / 米<input v-model.number="form.scale" type="number" min="0.000001" step="any" required/></label></div><label class="registered-check"><input v-model="form.registered" type="checkbox"/>已确认上述配准参数，启用空间叠加</label><div class="registration-camera"><h3>相机点位与视域</h3><select v-model="cameraId" aria-label="配准相机"><option v-for="device in monitor.devices" :key="device.id" :value="device.id">{{device.code}} · {{device.label}}</option></select><p class="dialog-note muted">C1 / C2 优先使用定位服务的标定坐标；其他相机在此填写同一米制坐标系中的测量值。</p><label class="registered-check"><input v-model="positionEnabled" type="checkbox"/>保存该相机的测量坐标</label><div v-if="positionEnabled" class="field-triple"><label v-for="axis in axes" :key="axis" class="form-field">{{axis.toUpperCase()}}（米）<input v-model.number="position[axis]" type="number" step="any" required/></label></div><label class="registered-check"><input v-model="directionEnabled" type="checkbox"/>已知该相机朝向与视场角</label><template v-if="directionEnabled"><div class="field-pair"><label class="form-field">水平朝向（°）<input v-model.number="direction.yawDeg" type="number" step="any" required/></label><label class="form-field">俯仰角（°）<input v-model.number="direction.pitchDeg" type="number" min="-90" max="90" step="any" required/></label></div><div class="field-triple"><label class="form-field">水平视角（°）<input v-model.number="direction.horizontalFovDeg" type="number" min="1" max="179" step="any" required/></label><label class="form-field">垂直视角（°）<input v-model.number="direction.verticalFovDeg" type="number" min="1" max="179" step="any" required/></label><label class="form-field">视域距离（米）<input v-model.number="direction.rangeMeters" type="number" min="0.1" step="any" required/></label></div></template><button class="btn" type="button" @click="applyCamera">应用到当前配准表</button><small v-if="cameraApplied" class="field-confirmation">已加入，点击下方“保存配准”写入配置。</small></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="dialog-actions"><button class="btn" type="button" @click="$emit('close')">取消</button><button class="btn primary" :disabled="busy">{{busy?'正在保存…':'保存配准'}}</button></div></fieldset></form></section></div></Teleport></template>
<script setup lang="ts">
import {ref,watch} from 'vue';import {X} from 'lucide-vue-next';
import {useDialogFocus} from '@/lib/dialog-focus';
import {useMonitorStore} from '@/stores/monitor';import {useCameraStore} from '@/stores/camera';import {useAuthStore} from '@/stores/auth';import {emptySceneConfig,type CameraDirection} from '@/types/monitor';
const props=defineProps<{open:boolean}>(),emit=defineEmits<{close:[]}>(),monitor=useMonitorStore(),camera=useCameraStore(),auth=useAuthStore();
useDialogFocus(()=>props.open,'.scene-registration',()=>emit('close'));
const axes=['x','y','z'] as const,form=ref(emptySceneConfig()),cameraId=ref(''),busy=ref(false),error=ref(''),positionEnabled=ref(false),directionEnabled=ref(false),cameraApplied=ref(false),position=ref({x:0,y:0,z:0}),direction=ref<CameraDirection>({yawDeg:0,pitchDeg:0,horizontalFovDeg:60,verticalFovDeg:40,rangeMeters:100});
const loading=ref(false),formReady=ref(false);let loadGeneration=0;
function loadCamera(){const p=form.value.cameraPositions?.[cameraId.value],d=form.value.cameraDirections?.[cameraId.value];positionEnabled.value=!!p;directionEnabled.value=!!d;position.value=p?{...p}:{x:0,y:0,z:0};direction.value=d?{...d}:{yawDeg:0,pitchDeg:0,horizontalFovDeg:60,verticalFovDeg:40,rangeMeters:100};cameraApplied.value=false}
watch(()=>props.open,async value=>{const generation=++loadGeneration;if(!value)return;formReady.value=false;loading.value=true;error.value='';try{await monitor.loadSceneConfig();if(!props.open||generation!==loadGeneration)return;form.value=JSON.parse(JSON.stringify(monitor.sceneConfig));form.value.cameraPositions??={};form.value.cameraDirections??={};cameraId.value=monitor.selectedCameraId||monitor.devices[0]?.id||'';loadCamera();formReady.value=true}catch(e){if(generation===loadGeneration)error.value='无法读取已保存的配准，未允许覆盖：'+(e as Error).message}finally{if(generation===loadGeneration)loading.value=false}});watch(cameraId,loadCamera);
function applyCamera(){if(!cameraId.value)return;form.value.cameraPositions??={};form.value.cameraDirections??={};if(positionEnabled.value)form.value.cameraPositions[cameraId.value]={...position.value};else delete form.value.cameraPositions[cameraId.value];if(directionEnabled.value)form.value.cameraDirections[cameraId.value]={...direction.value};else delete form.value.cameraDirections[cameraId.value];cameraApplied.value=true}
async function save(){if(busy.value||!formReady.value||!auth.can('devices'))return;applyCamera();busy.value=true;error.value='';try{await monitor.saveSceneConfig(form.value);camera.toast('模型配准已保存','success');emit('close')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
